from collections import deque

def transform(grid):
    g=[row[:] for row in grid]
    bg=min(set(v for row in g for v in row))
    # Flood background from image border; enclosed background pockets become 4.
    h,w=len(g),len(g[0])
    seen=set(); q=deque()
    for r in range(h):
        for c in range(w):
            if r in (0,h-1) or c in (0,w-1):
                if g[r][c]==bg and (r,c) not in seen:
                    seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=rr<h and 0<=cc<w and g[rr][cc]==bg and (rr,cc) not in seen:
                seen.add((rr,cc)); q.append((rr,cc))
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg and (r,c) not in seen: g[r][c]=4
    return g
